  3	import java.util.ArrayList;
  4	import java.util.Collections;
  5	import java.util.HashMap;
  6	
  7	public class Floor {
  8	
  9	    private ArrayList<Room> rooms;
 10	    private HashMap<String, Integer> prices;
 11	
 12	    // testing
 13	
 14	    public boolean isAvailable() {
 15	        return totalRooms() == totalRoomsAvailable();
 16	    }
 17	
 18	    // accessing
 19	
 20	    public ArrayList<Room> rooms() {
 21	        return rooms;
 22	    }
 23	
 24	    // accounting
 25	
 26	    public int totalLosses() {
 27	        int total;
 28	
 29	        total = 0;
 30	        for (Room room : rooms) {
 31	            if (room.isAvailable()) {
 32	                total = total + Collections.max(prices.values());
 33	            }
 34	        }
 35	
 36	        return total;
 37	    }
 38	
 39	    public int totalProfits() {
 40	        int total;
 41	
 42	        total = 0;
 43	        for (Room room : rooms) {
 44	            Integer roomTotal;
 45	            if (room.isOccupied()) {
 46	                roomTotal = room.profitUsingIfAbsentGuestType(prices, () -> {
 47	                    Floor.signalUnknownGuestType();
 48	                    return null;
 49	                });
 50	                total = total + roomTotal;
 51	            }
 52	        }
 53	
 54	        return total;
 55	    }
 56	
 57	    // setters
 58	
 59	    public void setNumberOfRooms(Number aNumberOfRooms) {
 60	        Floor.assertIsPositiveIfFalse(aNumberOfRooms, () -> Floor.signalNumberOfRoomsMustBePositive());
 61	        Floor.assertIsIntegerIfFalse(aNumberOfRooms, () -> Floor.signalNumberOfRoomsMustBeInteger());
 62	
 63	        initializeRoomsWith(aNumberOfRooms);
 64	    }
 65	
 66	    public void setPrices(HashMap<String, Integer> aPriceList) {
 67	        if (aPriceList.isEmpty()) {
 68	            Floor.signalNoPrices();
 69	        }
 70	
 71	        for (Integer price : aPriceList.values()) {
 72	            Floor.assertIsPositiveIfFalse(price, () -> Floor.signalPriceMustBePositive());
 73	        }
 74	
 75	        initializeWith(aPriceList);
 76	    }
 77	
 78	    // totals
 79	
 80	    public int totalRooms() {
 81	        return rooms.size();
 82	    }
 83	
 84	    public int totalRoomsAvailable() {
 85	        int count = 0;
 86	        for (Room room : rooms) {
 87	            if (room.isAvailable()) {
 88	                count = count + 1;
 89	            }
 90	        }
 91	        return count;
 92	    }
 93	
 94	    public int totalRoomsOccupied() {
 95	        int count = 0;
 96	        for (Room room : rooms) {
 97	            if (room.isOccupied()) {
 98	                count = count + 1;
 99	            }
100	        }
101	        return count;
102	    }
103	
104	    public int totalRoomsReserved() {
105	        int count = 0;
106	        for (Room room : rooms) {
107	            if (room.isReserved()) {
108	                count = count + 1;
109	            }
110	        }
111	        return count;
112	    }
113	
114	    // initialization
115	
116	    private void initializeRoomsWith(Number aNumberOfRooms) {
117	        int ix;
118	
119	        rooms = new ArrayList<>();
120	
121	        ix = 1;
122	        while (ix <= aNumberOfRooms.intValue()) {
123	            rooms.add(new Room());
124	            ix = ix + 1;
125	        }
126	    }
127	
128	    private void initializeWith(HashMap<String, Integer> aPriceList) {
129	        prices = aPriceList;
130	    }
131	
132	    // assertions (class side)
133	
134	    public static void assertIsIntegerIfFalse(Number aNumber, Runnable signalsBlock) {
135	        if (!(aNumber instanceof Integer)) {
136	            signalsBlock.run();
137	        }
138	    }
139	
140	    public static void assertIsPositiveIfFalse(Number aNumber, Runnable signalsBlock) {
141	        if (!(aNumber.doubleValue() > 0)) {
142	            signalsBlock.run();
143	        }
144	    }
145	
146	    // error messages (class side)
147	
148	    public static String numberOfRoomsMustBeIntegerErrorDescription() {
149	        return "Number of rooms must be integer";
150	    }
151	
152	    public static String numberOfRoomsMustBePositiveErrorDescription() {
153	        return "The number of rooms must be positive";
154	    }
155	
156	    public static String priceMustBeIntegerErrorDescription() {
157	        return "Price must be integer";
158	    }
159	
160	    public static String priceMustBePositiveErrorDescription() {
161	        return "Price must be positive";
162	    }
163	
164	    public static String pricesListCannotBeEmptyErrorDescription() {
165	        return "Prices List must not be empty";
166	    }
167	
168	    public static String unknownGuestTypeErrorDescription() {
169	        return "The guest type is unknown";
170	    }
171	
172	    // exceptions (class side)
173	
174	    public static void signalNoPrices() {
175	        throw new RuntimeException(Floor.pricesListCannotBeEmptyErrorDescription());
176	    }
177	
178	    public static void signalNumberOfRoomsMustBeInteger() {
179	        throw new RuntimeException(Floor.numberOfRoomsMustBeIntegerErrorDescription());
180	    }
181	
182	    public static void signalNumberOfRoomsMustBePositive() {
183	        throw new RuntimeException(Floor.numberOfRoomsMustBePositiveErrorDescription());
184	    }
185	
186	    public static void signalPriceMustBeInteger() {
187	        throw new RuntimeException(Floor.priceMustBeIntegerErrorDescription());
188	    }
189	
190	    public static void signalPriceMustBePositive() {
191	        throw new RuntimeException(Floor.priceMustBePositiveErrorDescription());
192	    }
193	
194	    public static void signalUnknownGuestType() {
195	        throw new RuntimeException(Floor.unknownGuestTypeErrorDescription());
196	    }
197	}
