  3	import java.util.ArrayList;
  4	
  5	public class Hotel {
  6	
  7	    private ArrayList<Floor> floors;
  8	    private int availableRoomsCount;
  9	
 10	    // initialization
 11	
 12	    public Hotel() {
 13	        availableRoomsCount = 0;
 14	    }
 15	
 16	    // accounting
 17	
 18	    public int totalLosses() {
 19	        int acc;
 20	
 21	        acc = 0;
 22	        for (Floor floor : floors) {
 23	            acc = acc + floor.totalLosses();
 24	        }
 25	
 26	        return acc;
 27	    }
 28	
 29	    public int totalProfits() {
 30	        int acc;
 31	
 32	        acc = 0;
 33	        for (Floor floor : floors) {
 34	            acc = acc + floor.totalProfits();
 35	        }
 36	
 37	        return acc;
 38	    }
 39	
 40	    // setters
 41	
 42	    public Hotel setFloors(ArrayList<Floor> aFloorsCollection) {
 43	        Hotel.assertHaveFloors(aFloorsCollection);
 44	
 45	        floors = aFloorsCollection;
 46	
 47	        availableRoomsCount = totalRooms();
 48	
 49	        return this;
 50	    }
 51	
 52	    // totals
 53	
 54	    public int totalRooms() {
 55	        int ix;
 56	        int acc;
 57	
 58	        acc = 0;
 59	
 60	        ix = 1;
 61	        while (ix <= floors.size()) {
 62	            Floor floor;
 63	            int jx;
 64	            floor = floors.get(ix - 1);
 65	
 66	            jx = 1;
 67	            while (jx <= floor.rooms().size()) {
 68	                acc = acc + 1;
 69	
 70	                jx = jx + 1;
 71	            }
 72	
 73	            ix = ix + 1;
 74	        }
 75	
 76	        return acc;
 77	    }
 78	
 79	    public int totalRoomsAvailable() {
 80	        return availableRoomsCount;
 81	    }
 82	
 83	    public int totalRoomsOccupied() {
 84	        int ix;
 85	        int acc;
 86	
 87	        acc = 0;
 88	
 89	        ix = 1;
 90	        while (ix <= floors.size()) {
 91	            Floor floor;
 92	            int jx;
 93	            floor = floors.get(ix - 1);
 94	
 95	            jx = 1;
 96	            while (jx <= floor.rooms().size()) {
 97	                Room room;
 98	                room = floor.rooms().get(jx - 1);
 99	                if (room.isOccupied()) {
100	                    acc = acc + 1;
101	                }
102	
103	                jx = jx + 1;
104	            }
105	
106	            ix = ix + 1;
107	        }
108	
109	        return acc;
110	    }
111	
112	    public int totalRoomsReserved() {
113	        int ix;
114	        int acc;
115	
116	        acc = 0;
117	
118	        ix = 1;
119	        while (ix <= floors.size()) {
120	            Floor floor;
121	            int jx;
122	            floor = floors.get(ix - 1);
123	
124	            jx = 1;
125	            while (jx <= floor.rooms().size()) {
126	                Room room;
127	                room = floor.rooms().get(jx - 1);
128	                if (room.isReserved()) {
129	                    acc = acc + 1;
130	                }
131	
132	                jx = jx + 1;
133	            }
134	
135	            ix = ix + 1;
136	        }
137	
138	        return acc;
139	    }
140	
141	    // testing
142	
143	    public boolean isEmpty() {
144	        int ix;
145	        boolean acc;
146	
147	        acc = true;
148	
149	        ix = 1;
150	        while (ix <= floors.size()) {
151	            Floor floor;
152	            int jx;
153	            floor = floors.get(ix - 1);
154	
155	            jx = 1;
156	            while (jx <= floor.rooms().size()) {
157	                Room room;
158	                room = floor.rooms().get(jx - 1);
159	                acc = acc && room.isAvailable();
160	
161	                jx = jx + 1;
162	            }
163	
164	            ix = ix + 1;
165	        }
166	
167	        return acc;
168	    }
169	
170	    // guests
171	
172	    public void receiveAtFloorAtRoom(String aGuestType, int aFloorNumber, int aRoomNumber) {
173	        Floor floor;
174	        Room room;
175	
176	        if (aFloorNumber < 1 || aFloorNumber > floors.size()) {
177	            Hotel.signalFloorNumberDoesNotExist();
178	        }
179	        floor = floors.get(aFloorNumber - 1);
180	        if (aRoomNumber < 1 || aRoomNumber > floor.rooms().size()) {
181	            Hotel.signalRoomNumberDoesNotExist();
182	        }
183	        room = floor.rooms().get(aRoomNumber - 1);
184	
185	        room.receive(aGuestType);
186	
187	        availableRoomsCount = availableRoomsCount - 1;
188	    }
189	
190	    public void receiveWithReservationAtFloorAtRoom(String aGuestType, int aFloorNumber, int aRoomNumber) {
191	        Floor floor;
192	        Room room;
193	
194	        if (aFloorNumber < 1 || aFloorNumber > floors.size()) {
195	            Hotel.signalFloorNumberDoesNotExist();
196	        }
197	        floor = floors.get(aFloorNumber - 1);
198	        if (aRoomNumber < 1 || aRoomNumber > floor.rooms().size()) {
199	            Hotel.signalRoomNumberDoesNotExist();
200	        }
201	        room = floor.rooms().get(aRoomNumber - 1);
202	
203	        room.receiveWithReservation(aGuestType);
204	    }
205	
206	    public void reserveRoomAtFloor(int aRoomNumber, int aFloorNumber) {
207	        Floor floor;
208	        Room room;
209	
210	        if (aFloorNumber < 1 || aFloorNumber > floors.size()) {
211	            Hotel.signalFloorNumberDoesNotExist();
212	        }
213	        floor = floors.get(aFloorNumber - 1);
214	        if (aRoomNumber < 1 || aRoomNumber > floor.rooms().size()) {
215	            Hotel.signalRoomNumberDoesNotExist();
216	        }
217	        room = floor.rooms().get(aRoomNumber - 1);
218	
219	        room.reserve();
220	
221	        availableRoomsCount = availableRoomsCount - 1;
222	    }
223	
224	    // assertions (class side)
225	
226	    public static void assertHaveFloors(ArrayList<Floor> aFloorsCollection) {
227	        if (aFloorsCollection.isEmpty()) {
228	            Hotel.signalNoFloors();
229	        }
230	    }
231	
232	    // error description (class side)
233	
234	    public static String floorNumberDoesNotExistErrorDescription() {
235	        return "Floor number does not exist";
236	    }
237	
238	    public static String noFloorsErrorDescription() {
239	        return "Cannot have a Hotel without floors";
240	    }
241	
242	    public static String roomNumberDoesNotExistErrorDescription() {
243	        return "Room number does not exist";
244	    }
245	
246	    // exceptions (class side)
247	
248	    public static void signalFloorNumberDoesNotExist() {
249	        throw new RuntimeException(Hotel.floorNumberDoesNotExistErrorDescription());
250	    }
251	
252	    public static void signalNoFloors() {
253	        throw new RuntimeException(Hotel.noFloorsErrorDescription());
254	    }
255	
256	    public static void signalRoomNumberDoesNotExist() {
257	        throw new RuntimeException(Hotel.roomNumberDoesNotExistErrorDescription());
258	    }
259	}

