 14	    }
 15	
 16	    // accounting
 17	
 18	    public int totalLosses() {
 19	        int acc;
 20	
 21	        acc = 0;
 22	        for (Floor floor : floors) {
 23	            acc = acc + floor.totalLosses();
 24	        }
 25	
 26	        return acc;
 27	    }
