 29	    public int totalProfits() {
 30	        int acc;
 31	
 32	        acc = 0;
 33	        for (Floor floor : floors) {
 34	            acc = acc + floor.totalProfits();
 35	        }
 36	
 37	        return acc;
 38	    }
 39	
 40	    // setters
 41	
 42	    public Hotel setFloors(ArrayList<Floor> aFloorsCollection) {
 43	        Hotel.assertHaveFloors(aFloorsCollection);
 44	
 45	        floors = aFloorsCollection;
 46	
 47	        availableRoomsCount = totalRooms();
 48	
 49	        return this;
 50	    }
 51	
 52	    // totals
 53	
 54	    public int totalRooms() {
 55	        int ix;
 56	        int acc;
 57	
 58	        acc = 0;
 59	
 60	        ix = 1;
 61	        while (ix <= floors.size()) {
 62	            Floor floor;
 63	            int jx;
 64	            floor = floors.get(ix - 1);
 65	
 66	            jx = 1;
 67	            while (jx <= floor.rooms().size()) {
 68	                acc = acc + 1;
 69	
 70	                jx = jx + 1;
 71	            }
 72	
 73	            ix = ix + 1;
 74	        }
 75	
 76	        return acc;
 77	    }
 78	
 79	    public int totalRoomsAvailable() {
 80	        return availableRoomsCount;
 81	    }
 82	
 83	    public int totalRoomsOccupied() {
 84	        int ix;
 85	        int acc;
 86	
 87	        acc = 0;
 88	
 89	        ix = 1;
 90	        while (ix <= floors.size()) {
 91	            Floor floor;
 92	            int jx;
 93	            floor = floors.get(ix - 1);
 94	
 95	            jx = 1;
 96	            while (jx <= floor.rooms().size()) {
 97	                Room room;
 98	                room = floor.rooms().get(jx - 1);
 99	                if (room.isOccupied()) {
100	                    acc = acc + 1;
101	                }
102	
103	                jx = jx + 1;
104	            }
105	
106	            ix = ix + 1;
107	        }
108	
109	        return acc;
110	    }
